  "components/realtime-sales.jsx":
    'import React from \'react\';\nimport {\n  BarChart,\n  Bar,\n  Rectangle,\n  XAxis,\n  YAxis,\n  CartesianGrid,\n  Tooltip,\n  Legend,\n  ResponsiveContainer,\n} from \'recharts\';\n\nconst data = [\n  {\n    name: \'Page A\',\n    uv: 4000,\n    pv: 2400,\n    amt: 2400,\n  },\n  {\n    name: \'Page B\',\n    uv: 3000,\n    pv: 1398,\n    amt: 2210,\n  },\n  {\n    name: \'Page C\',\n    uv: 2000,\n    pv: 9800,\n    amt: 2290,\n  },\n  {\n    name: \'Page D\',\n    uv: 2780,\n    pv: 3908,\n    amt: 2000,\n  },\n  {\n    name: \'Page E\',\n    uv: 1890,\n    pv: 4800,\n    amt: 2181,\n  },\n  {\n    name: \'Page F\',\n    uv: 2390,\n    pv: 3800,\n    amt: 2500,\n  },\n  {\n    name: \'Page G\',\n    uv: 3490,\n    pv: 4300,\n    amt: 2100,\n  },\n];\n\nexport const RealtimeSales = () => {\n  return (\n    <div className="px-2 w-full w-full lg:w-1/2 mb-5 lg:mb-0">\n      <div className="_real_time_sales_card  border border-gray-200 bg-white">\n        <div className="_card_header flex items-center justify-between px-5 pt-5">\n          <h6 className="mb-4">Real Time Sales</h6>\n          <span className="text-xs font-light text-gray-700">This Week</span>\n        </div>\n        <div className="_card_body px-5">\n          <div className="_card_body_top flex w-full gap-8 mb-5">\n            <div>\n              <h6 className="text-xl font-semibold text-gray-800">\n                <span>$</span>150,200<small>.00</small>\n              </h6>\n              <label className="text-sm font-light">Total Sales</label>\n            </div>\n            <div>\n              <h6 className="text-xl font-semibold text-gray-800">\n                <span>$</span>21,830<small>.25</small>\n              </h6>\n              <label className="text-sm font-light">Avg. Sales per Day</label>\n            </div>\n          </div>\n          <div className="flex justify-between mb-4">\n            <label className="_content_label text-xs font-bold text-gray-500">\n              Sales Per Hour\n            </label>\n            <div className="_chart_legend flex items-center gap-4">\n              <div className="flex items-center text-[10px] font-medium tracking-wide uppercase">\n                <div className="_bg-primary mr-1 h-2 w-2 bg-blue-500"></div>\n                <p>Today</p>\n              </div>\n              <div className="flex items-center text-[10px] font-medium tracking-wide uppercase">\n                <div className="_bg-teal mr-1 h-2 w-2 bg-gray-500"></div>\n                <p>Yesterday</p>\n              </div>\n            </div>\n          </div>\n          <div className="_chart_wrapper flex-1 w-full h-[200px]">\n            <ResponsiveContainer width="100%" height="100%">\n              <BarChart\n                width={500}\n                height={300}\n                data={data}\n                margin={{\n                  top: 0,\n                  right: 0,\n                  left: 0,\n                  bottom: 0,\n                }}\n              >\n                <CartesianGrid strokeDasharray="3 3" />\n                <XAxis dataKey="name" tick={{ fontSize: 9, fill: \'#999\' }} />\n                <YAxis width={35} tick={{ fontSize: 9, fill: \'#999\' }} />\n                <Tooltip />\n                <Bar dataKey="pv" fill="#006fd9" />\n                <Bar dataKey="uv" fill="#dee2e6" />\n              </BarChart>\n            </ResponsiveContainer>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};\n',
